<template>
 <div class="return-documents" v-loading="loading || busy">
  <div class="heading"><div><h3>退回单管理</h3><p class="muted">每张单据独立下发、截单和入账；重新安排只生成尚未实收的剩余数量。</p></div><el-button size="small" @click="load">刷新退回单</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-alert v-if="actual && Number(actual.pending_review_count)" title="有截单后到达的实收回传，尚未入账。先核对原始回传及其他退回安排，再确认接收或拒绝。" type="warning" :closable="false" />
  <div v-if="actual" class="totals">申请退回 <b>{{ exchange.requested_quantity }}</b> 件 · 累计实收 <b>{{ actual.accepted_quantity }}</b> 件 · 已入账 <b>{{ actual.posted_quantity }}</b> 件 · 尚未实收 <b>{{ remaining }}</b> 件</div>
  <el-empty v-if="!error && !documents.length" description="尚未生成退回单" />
  <article v-for="d in documents" :key="d.id" class="return-document">
   <header><div class="document-number"><router-link :to="ticket(d)">{{ d.return_sn }}</router-link><el-button type="text" icon="el-icon-document-copy" v-clipboard:copy="d.return_sn" v-clipboard:success="copied" title="复制退回单号" /><el-tag size="mini" effect="plain">第 {{ d.generation }} 次安排</el-tag></div><el-tag size="small" :type="d.cancel_state === 'CONFIRMED' ? unreceived(d) === 0 ? 'success' : 'info' : d.cancel_state !== 'NONE' ? 'warning' : 'success'">{{ cancelLabel(d) }}</el-tag></header>
   <el-descriptions border size="small" :column="2"><el-descriptions-item label="商品 / SKU">{{ exchange.original_goods && (exchange.original_goods.goodsName || exchange.original_goods.goods_name) || d.sku_sn }}<div class="muted">{{ d.sku_sn }}</div></el-descriptions-item><el-descriptions-item label="退回仓 / 货主">{{ d.store_code }} · {{ d.real_store_code }}<div class="muted">货主 {{ d.owner_code }}</div></el-descriptions-item><el-descriptions-item label="来源">原平台子单 {{ exchange.platform_oid }}<div class="muted">原发货单 {{ source.original_shipment_sn || '—' }} · 发货明细 #{{ exchange.source_shipment_line_id }}</div></el-descriptions-item><el-descriptions-item label="仓库受理">{{ dispatchLabel(d.dispatch_state,d) }}<div class="muted">仓库单号 {{ d.external_order || '尚未返回' }} · {{ d.warehouse_status || '尚无仓库状态' }}</div></el-descriptions-item><el-descriptions-item label="数量">计划 {{ d.quantity }} · 累计实收 {{ d.accepted_quantity }} · 累计入账 {{ d.posted_quantity }}<div class="muted">当前未收 {{ unreceived(d) }} 件<span v-if="d.cancel_state === 'CONFIRMED' && unreceived(d) > 0">（原安排剩余已停止）</span></div><div v-if="d.cancelled_at" class="muted">{{ cutoffHistory(d) }}</div></el-descriptions-item><el-descriptions-item label="本次寄回地址">{{ d.return_address || (exchange.approved_snapshot || {}).return_address || '按已核对地址寄回' }}<div class="muted">{{ d.return_contact || (exchange.approved_snapshot || {}).return_contact }}</div></el-descriptions-item><el-descriptions-item label="截单依据">{{ d.cancel_reason || '—' }}<div class="muted">{{ d.cancel_actor }} {{ d.cancelled_at || '' }}</div></el-descriptions-item></el-descriptions>
   <el-alert v-if="d.last_error" :title="d.last_error" type="warning" :closable="false" />
   <div class="document-actions"><el-button v-hasPermi="['order:exchange:execute']" size="small" @click="command(d,'query')">查询仓库原单</el-button><el-button v-if="editable && d.cancel_state === 'NONE' && d.dispatch_state === 'FAILED' && !Number(exchange.fulfillment_hold)" v-hasPermi="['order:exchange:execute']" size="small" @click="command(d,'retry')">重试明确失败的下发</el-button><el-button v-if="Number(d.accepted_quantity) > Number(d.posted_quantity)" v-hasPermi="['order:exchange:execute']" size="small" @click="command(d,'posting')">核对原回执记账</el-button><el-button v-if="editable && d.cancel_state !== 'CONFIRMED' && Number(d.accepted_quantity) < Number(d.quantity)" v-hasPermi="['order:exchange:execute']" size="small" @click="open('cancel',d)">申请退回截单</el-button><el-button v-if="editable && d.id === documents[0].id && d.cancel_state === 'CONFIRMED' && exchange.control_state === 'HOLD' && remaining > 0" v-hasPermi="['order:exchange:execute']" size="small" @click="open('rearrange',d)">重新安排剩余退回</el-button><el-button type="text" @click="selected=d;detailVisible=true">查看本单实收与回传</el-button><router-link :to="logs(d)">仓库交互日志</router-link></div>
  </article>
  <section v-if="reviews.length"><h3>截单后实收 · 人工核对</h3><p class="muted">下表展示每条回传的本次数量；已确认实收的数量已计入上方对应退回单的累计实收，不重复累计。待核对回传不增加库存；确认前须先停止其他未结束退回安排。</p><el-table :data="reviews"><el-table-column label="退回单 / 消息" min-width="280"><template slot-scope="s">{{ s.row.return_sn }}<div class="muted">{{ s.row.message_id }}</div></template></el-table-column><el-table-column label="本次回传数量" prop="quantity" width="125" /><el-table-column label="结果" width="115"><template slot-scope="s">{{ ({WAIT_REVIEW:'待人工核对',ACCEPTED:'已确认实收',REJECTED:'已拒绝'})[s.row.state] }}</template></el-table-column><el-table-column label="原因 / 依据" prop="reason" min-width="230" /><el-table-column label="操作" width="100"><template slot-scope="s"><el-button v-if="s.row.state === 'WAIT_REVIEW'" v-hasPermi="['order:exchange:execute']" type="text" @click="open('review',documents.find(d=>Number(d.id)===Number(s.row.task_id)),s.row)">核对处理</el-button></template></el-table-column></el-table></section>
  <el-dialog :title="titles[action]" :visible.sync="visible" width="min(690px,96vw)" append-to-body :close-on-click-modal="false"><el-alert :title="hints[action]" type="warning" :closable="false" /><p class="number">{{ selected.return_sn }}</p><el-form label-width="115px"><el-form-item v-if="action === 'cancel'" label="截单目的"><el-radio-group v-model="form.mode"><el-radio label="WITHDRAW">撤回重新安排</el-radio><el-radio label="TERMINATE">终止剩余退回</el-radio></el-radio-group></el-form-item><template v-if="action === 'rearrange'"><el-form-item label="剩余数量">{{ remaining }} 件</el-form-item><el-form-item label="新退回虚拟仓"><el-select v-model="form.store_code" filterable><el-option v-for="w in warehouses" :key="w.code" :value="w.code" :label="w.name+'（'+w.code+'）'" /></el-select></el-form-item><el-form-item label="本次寄回地址"><el-input v-model.trim="form.return_address" maxlength="500" placeholder="请核对新仓对应的买家寄回地址" /></el-form-item><el-form-item label="寄回联系信息"><el-input v-model.trim="form.return_contact" maxlength="200" /></el-form-item></template><el-form-item v-if="action === 'review'" label="核对结论"><el-radio-group v-model="form.decision"><el-radio label="ACCEPT">确认实际收到</el-radio><el-radio label="REJECT">拒绝本次回传</el-radio></el-radio-group></el-form-item><el-form-item label="处理依据"><el-input v-model.trim="form.reason" type="textarea" :maxlength="action === 'rearrange' ? 500 : 200" show-word-limit /></el-form-item><el-form-item v-if="action === 'review'" label="核对凭证"><el-input v-model.trim="form.evidence" type="textarea" maxlength="250" show-word-limit /></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" @click="submit">{{ action === 'cancel' ? '提交截单申请' : action === 'rearrange' ? '生成剩余退回单' : '保存核对结果' }}</el-button></span></el-dialog>
  <el-dialog title="退回单实收与回传" :visible.sync="detailVisible" width="min(1000px,96vw)" append-to-body><p class="number">{{ selected.return_sn }}</p><el-table :data="actual && (actual.lines || []).filter(l=>l.return_sn === selected.return_sn) || []" empty-text="尚无有效实收"><el-table-column label="SKU / 批次" min-width="200"><template slot-scope="s">{{ s.row.sku_sn }}<div class="muted">{{ s.row.batch_code }}</div></template></el-table-column><el-table-column label="本次良品 / 次品" width="150"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column label="入账" width="90"><template slot-scope="s">{{ Number(s.row.posted) ? '已入账' : '待入账' }}</template></el-table-column><el-table-column label="回传消息" prop="message_id" min-width="200" /><el-table-column label="时间" prop="create_time" min-width="165" /></el-table><span slot="footer"><el-button @click="detailVisible=false">关闭</el-button></span></el-dialog>
 </div>
</template>
<script>
import { exchangeReturnReport, exchangeAction, exchangeCatalog } from '@/api/order/exchange'
import { ended } from './exchangePresentation'
export default {
 props:{exchange:{type:Object,required:true}},
 data(){return {loading:false,busy:false,error:'',actual:null,sequence:0,visible:false,detailVisible:false,selected:{},action:'',form:{},warehouses:[],titles:{cancel:'申请退回入库截单',rearrange:'重新安排剩余退回',review:'核对截单后实收'},hints:{cancel:'先暂停新增履约，再向仓库申请停止剩余收货。已实收入账保留，不代表已拦截买家快递，也不会自动取消整张换货。',rearrange:'原单必须确认停止且没有待核对回传。只生成未实收的剩余数量；生成后仍保持挂起，核对安排后再恢复履约。',review:'仅确认真实仓库收货。确认后按原成本入账一次，不撤销截单记录；如已生成新退回安排，请先截停新单。'}}},
 computed:{documents(){return this.actual && this.actual.documents || []},reviews(){return this.actual && this.actual.reviews || []},remaining(){return this.actual ? Math.max(0,Number(this.exchange.requested_quantity)-Number(this.actual.accepted_quantity)) : 0},editable(){return !ended(this.exchange)&&!this.exchange.linked_exchange_id},source(){return (this.exchange.approved_snapshot||{}).return_basis||{}}},
 watch:{'exchange.control_version'(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++},
 methods:{unreceived(d){return Math.max(0,Number(d.quantity)-Number(d.accepted_quantity))},confirmedAfterCutoff(d){return Math.max(0,Number(d.accepted_quantity)-Math.max(0,Number(d.quantity)-Number(d.cancelled_quantity)))},cutoffHistory(d){const later=this.confirmedAfterCutoff(d);return '截单时未收 '+d.cancelled_quantity+' 件（历史快照）'+(later>0?'；后经人工确认收回 '+later+' 件':'')},cancelLabel(d){if(d.cancel_state==='CONFIRMED'&&this.unreceived(d)===0)return '已收齐 · 曾截单';const s=d.cancel_state;return ({NONE:'正常退回安排',PENDING:'截单待确认',UNKNOWN:'截单结果不明',CONFIRMED:'剩余已停止',REJECTED:'仓库拒绝截单'})[s]||s},dispatchLabel(s,d){if(d&&d.cancel_state==='CONFIRMED'&&this.unreceived(d)===0)return '原安排曾截单，现已收齐';return ({PENDING:'待下发',SENDING:'下发中',UNKNOWN:'结果待确认',ACCEPTED:'仓库已接收',FAILED:'下发失败',CANCELED:'原安排已停止'})[s]||s},ticket(d){return {path:'/oms-supplychain/wmsTickets',query:{sn:d.return_sn,documentId:d.ticket_id||undefined,sourceNumber:this.exchange.exchange_sn}}},logs(d){return {path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:d.return_sn,allTime:'true'}}},copied(){this.$message.success('单号已复制')},async load(){const seq=++this.sequence;this.loading=true;try{const r=await exchangeReturnReport(this.exchange.id);if(seq===this.sequence){this.actual=r.data.actual||null;this.error=''}}catch(_){if(seq===this.sequence){this.actual=null;this.error='退回单加载失败，请刷新；未知数量未按零处理'}}finally{if(seq===this.sequence)this.loading=false}},async open(action,d,review){this.action=action;this.selected=d;this.form={mode:'WITHDRAW',store_code:d.store_code,reason:'',return_address:d.return_address||(this.exchange.approved_snapshot||{}).return_address||'',return_contact:d.return_contact||(this.exchange.approved_snapshot||{}).return_contact||'',evidence:'',decision:'REJECT',review_id:review&&review.id};if(action==='rearrange'){const c=(await exchangeCatalog()).data;this.warehouses=(c.warehouses||[]).map(w=>({code:w.wms_simulation_code,name:w.wms_simulation_name||w.wms_simulation_code}))}this.visible=true},async command(d,action,body={}){if(this.busy)return;this.busy=true;try{await exchangeAction(this.exchange.id,'return-documents/'+d.id+'/'+action,{...body,document_version:d.control_version,control_version:this.exchange.control_version});this.visible=false;this.$emit('changed');await this.load();this.$message.success('已处理，请查看原单结果')}finally{this.busy=false}},async submit(){if(!this.form.reason)return this.$message.warning('请填写处理依据');if(this.action==='rearrange'&&(!this.form.store_code||!this.form.return_address||!this.form.return_contact))return this.$message.warning('请填写本次退回仓、寄回地址和联系信息');if(this.action==='review'&&!this.form.evidence)return this.$message.warning('请填写核对凭证');if(this.action==='cancel'){if(this.busy)return;this.busy=true;try{await exchangeAction(this.exchange.id,'control/request',{kind:'RETURN',document_id:this.selected.id,mode:this.form.mode,reason:this.form.reason,control_version:this.exchange.control_version});this.visible=false;this.$emit('changed');await this.load();this.$message.success('已登记截单，请核对原单结果')}finally{this.busy=false}}else return this.command(this.selected,this.action,{...this.form,quantity:this.remaining})}}
}
</script>
<style scoped>.heading,.return-document header,.document-number,.document-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.heading{justify-content:space-between}.heading h3{margin-bottom:8px}.muted{color:#8291a5;font-size:12px;line-height:1.8}.totals{background:#f1f6fc;padding:18px;border-radius:8px;margin:16px 0;color:#536982}.totals b{color:#263c57}.return-document{border:1px solid #e1e8f0;border-radius:8px;padding:18px;margin:18px 0}.return-document header{justify-content:space-between;margin-bottom:16px}.document-number>a,.number{font-weight:600;overflow-wrap:anywhere;color:#2877b9}.document-actions{margin-top:16px}.document-actions .el-button{margin:0}.document-actions>a{color:#1683e5;font-size:13px}.el-alert{margin:12px 0}.el-form{margin-top:20px}.el-select{width:100%}</style>
